mapper.select:
SELECT id,user_id,title,content,comment_count,published_at,post_type,category_id
FROM post WHERE deleted_at IS NULL AND status=#{status} AND NOT EXISTS(SELECT 1 FROM post_growth_record g WHERE g.post_id=post.id)
AND post_type=#{postType}
AND category_id=#{categoryId}
AND EXISTS (SELECT 1 FROM post_topic pt WHERE pt.post_id=post.id AND pt.topic_id=#{topicId})
AND user_id=#{userId}
AND MATCH(content) AGAINST(#{keyword} IN BOOLEAN MODE)
AND id < #{lastId}
AND admin_hidden=FALSE AND (audit_status=1 OR (audit_status=0 AND community_version=TRUE AND temporary_visible_until > DATE_ADD(#{pendingAfter},INTERVAL 10 MINUTE)))

    AND (SELECT COUNT(*) FROM comment c WHERE c.target_type=1 AND c.target_id=post.id AND c.parent_id IS NULL AND c.status=1 AND c.audit_status=1 AND c.deleted_at IS NULL AND NOT () AND c.first_published_at IS NOT NULL AND c.question_version=post.question_version)
     > 0 = 0

ORDER BY id DESC LIMIT #{pageSize}

SELECT id, title, content, like_count, comment_count, view_count, published_at FROM post WHERE NOT EXISTS(SELECT 1 FROM post_growth_record g WHERE g.post_id=post.id) AND status = 2 AND audit_status = 1 AND admin_hidden=FALSE AND deleted_at IS NULL AND id IN
#{id}
ORDER BY id, published_at DESC

SELECT COALESCE(view_count, 0)
FROM post
WHERE id = #{id}

SELECT id, status, audit_status, is_pinned, is_featured, deleted_at
FROM post
WHERE id = #{postId}

mapper.update:
UPDATE post
SET view_count = COALESCE(view_count, 0) + #{delta}
WHERE id = #{id}
